/// <summary>
/// Generates an on-demand ZPL label preview. Invoked from the <c>AAXWHSLabelPreview</c> action menu
/// item on the <c>WHSLabelLayout</c> and <c>WHSDocumentRoutingLayout</c> forms, resolves the layout's
/// ZPL, substitutes tokens through the standard <c>WhsDocumentRoutingTranslator</c>, renders the
/// PNG images, and opens the <c>AAXWHSLabelPreviewDialog</c> form.
/// </summary>
public final class AAXWHSLabelPreviewController
{
}

Method.Source:
/// <summary>
/// Entry point invoked by the AAXWHSLabelPreview action menu item. Builds the preview context for
/// the selected layout with the most recent seed record, opens the preview dialog, and refreshes
/// the calling form when the dialog closes.
/// </summary>
/// <param name = "_args">The menu item arguments carrying the selected layout record.</param>
public static void main(Args _args)
{
    AAXWHSLabelPreviewContext   context;
    Args                        dialogArgs;
    FormRun                     formRun;

    if (!_args || !_args.record())
    {
        return;
    }

    // Build the preview from the most recent seed record
    context = AAXWHSLabelPreviewController::buildContext(_args.record(), 0, 0);
    if (!context)
    {
        // A resolution gate already reported the reason
        return;
    }

    dialogArgs = new Args(formStr(AAXWHSLabelPreviewDialog));
    dialogArgs.parmObject(context);

    formRun = classfactory.formRunClass(dialogArgs);
    formRun.init();
    formRun.run();
    formRun.wait();

    // Refresh the calling form so a saved ZPL edit is shown immediately
    AAXWHSLabelPreviewController::refreshCallerLayoutForm(_args);
}

/// <summary>
/// Re-reads the calling layout form's data source after the preview dialog closes so a ZPL edit
/// saved from the dialog is shown without a manual refresh. Does nothing when not launched
/// from a form.
/// </summary>
/// <param name = "_args">The menu item arguments whose caller is the launching form.</param>
private static void refreshCallerLayoutForm(Args _args)
{
    FormRun         callerFormRun;
    FormDataSource  callerDataSource;

    if (!_args)
    {
        return;
    }

    callerFormRun = _args.caller() as FormRun;
    if (!callerFormRun)
    {
        return;
    }

    callerDataSource = callerFormRun.dataSource();
    if (callerDataSource)
    {
        callerDataSource.research(true);
    }
}

/// <summary>
/// Resolves the previewable ZPL for a layout record. Document routing layouts return their ZPL
/// field; label layouts return the ZPL of the active version. Shows an information message and
/// returns an empty string when the layout cannot be previewed.
/// </summary>
/// <param name = "_layoutRecord">A <c>WHSLabelLayout</c> or <c>WHSDocumentRoutingLayout</c> record.</param>
/// <returns>The layout's ZPL, or an empty string when the layout cannot be previewed.</returns>
public static str resolveLayoutZpl(Common _layoutRecord)
{
    WHSDocumentRoutingLayout    documentRoutingLayout;
    WHSLabelLayout              labelLayout;
    WHSLabelLayoutVersion       labelLayoutVersion;
    str                         zpl;

    if (!_layoutRecord || _layoutRecord.RecId == 0)
    {
        return '';
    }

    switch (_layoutRecord.TableId)
    {
        case tableNum(WHSDocumentRoutingLayout):
            // The ZPL is stored directly on the document routing layout
            documentRoutingLayout = _layoutRecord as WHSDocumentRoutingLayout;
            zpl = documentRoutingLayout.ZPL;
            break;

        case tableNum(WHSLabelLayout):
            labelLayout = _layoutRecord as WHSLabelLayout;

            // Only the ZPL definition type can be previewed
            if (labelLayout.DefinitionType != WHSLabelLayoutDefinitionType::ZPL)
            {
                info("@AAXWarehouseTools:PreviewZplOnly");
                return '';
            }

            // The ZPL of a label layout is stored on its active version
            select firstonly ZPL from labelLayoutVersion
                where labelLayoutVersion.RecId == labelLayout.ActiveVersion;
            zpl = labelLayoutVersion.ZPL;
            break;

        default:
            return '';
    }

    if (!zpl)
    {
        info("@AAXWarehouseTools:NoActiveVersion");
        return '';
    }

    return zpl;
}

/// <summary>
/// Resolves the seed table for a layout record. Prefers the first enabled data source of the
/// layout's data source query, then the custom label root table, and otherwise maps the layout
/// type to its natural table. Defaults to <c>WHSLicensePlateLabel</c>.
/// </summary>
/// <param name = "_layoutRecord">A <c>WHSLabelLayout</c> or <c>WHSDocumentRoutingLayout</c> record.</param>
/// <returns>The table id of the seed table for the layout.</returns>
public static TableId resolveSeedTable(Common _layoutRecord)
{
    WHSLabelLayout          labelLayout;
    WHSLabelLayoutDataSource layoutDataSource;
    SysDictTable            customRoot;
    TableId                 fromQuery;
    TableId                 seedTableId = tableNum(WHSLicensePlateLabel);

    if (!_layoutRecord || _layoutRecord.RecId == 0)
    {
        return seedTableId;
    }

    if (_layoutRecord.TableId == tableNum(WHSDocumentRoutingLayout))
    {
        // Document routing layouts are driven by license plate labels
        return tableNum(WHSLicensePlateLabel);
    }

    if (_layoutRecord.TableId != tableNum(WHSLabelLayout))
    {
        return seedTableId;
    }

    labelLayout = _layoutRecord as WHSLabelLayout;

    // Prefer the first enabled data source of the layout's own query
    if (labelLayout.LabelLayoutDataSource)
    {
        select firstonly DataSourceQuery, CustomLabelRootDataSourceTable from layoutDataSource
            where layoutDataSource.LabelLayoutDataSourceId == labelLayout.LabelLayoutDataSource;

        if (layoutDataSource.RecId != 0)
        {
            fromQuery = AAXWHSLabelPreviewController::firstDataSourceTableFromPackedQuery(layoutDataSource.DataSourceQuery);
            if (fromQuery)
            {
                return fromQuery;
            }

            // The custom label root table is stored by name
            if (layoutDataSource.CustomLabelRootDataSourceTable)
            {
                customRoot = SysDictTable::newName(layoutDataSource.CustomLabelRootDataSourceTable);
                if (customRoot)
                {
                    return customRoot.id();
                }
            }
        }
    }

    // Map the layout type to its natural table
    switch (labelLayout.LayoutType)
    {
        case WHSLabelLayoutType::LicensePlateLabel:
            seedTableId = tableNum(WHSLicensePlateLabel);
            break;

        case WHSLabelLayoutType::ContainerLabel:
            seedTableId = tableNum(WHSContainerTable);
            break;

        case WHSLabelLayoutType::CustomLabel:
            // No data source is bound, so fall back to the license plate label
            seedTableId = tableNum(WHSLicensePlateLabel);
            break;

        default:
            seedTableId = tableNum(WHSLicensePlateLabel);
            break;
    }

    return seedTableId;
}

/// <summary>
/// Unpacks a packed query and returns the table id of its first enabled data source. Any
/// failure is swallowed so the caller can fall back to the layout type map.
/// </summary>
/// <param name = "_packedQuery">The packed data source query container.</param>
/// <returns>The table id of the first enabled data source, or 0 when it cannot be determined.</returns>
private static TableId firstDataSourceTableFromPackedQuery(container _packedQuery)
{
    Query                   query;
    QueryBuildDataSource    qbds;
    TableId                 result = 0;
    int                     dsCount;
    int                     i;

    if (_packedQuery == conNull())
    {
        return 0;
    }

    try
    {
        query = new Query(_packedQuery);
        dsCount = query.dataSourceCount();

        for (i = 1; i <= dsCount; ++i)
        {
            qbds = query.dataSourceNo(i);
            if (qbds && qbds.enabled() && qbds.table())
            {
                result = qbds.table();
                break;
            }
        }
    }
    catch
    {
        // Fall back to the layout type map on any unpack failure
        result = 0;
    }

    return result;
}

/// <summary>
/// Builds the preview context for a layout record and a chosen seed record by reading the
/// source ZPL from the layout. Used by the menu item and by the dialog's refresh action.
/// </summary>
/// <param name = "_layoutRecord">A <c>WHSLabelLayout</c> or <c>WHSDocumentRoutingLayout</c> record.</param>
/// <param name = "_seedTableId">The seed table id, or 0 to resolve it from the layout.</param>
/// <param name = "_seedRecId">The seed record id, or 0 to use the most recent record.</param>
/// <param name = "_widthMm">The override width in millimeters, or 0 to use the label's own size.</param>
/// <param name = "_heightMm">The override height in millimeters, or 0 to use the label's own size.</param>
/// <param name = "_dpmm">The override density in dots per millimeter, or 0 to use the configured default.</param>
/// <returns>A populated <c>AAXWHSLabelPreviewContext</c>, or null when the layout cannot be previewed.</returns>
public static AAXWHSLabelPreviewContext buildContext(
    Common  _layoutRecord,
    TableId _seedTableId,
    RecId   _seedRecId,
    real    _widthMm = 0,
    real    _heightMm = 0,
    int     _dpmm = 0)
{
    // An empty source override reads the source from the layout
    return AAXWHSLabelPreviewController::buildContextFromSource(
        _layoutRecord, '', _seedTableId, _seedRecId, _widthMm, _heightMm, _dpmm);
}

/// <summary>
/// Builds the preview context from a caller-supplied source ZPL instead of the layout's stored
/// source, so the dialog can preview unsaved edits through the same pipeline as <c>buildContext</c>.
/// </summary>
/// <param name = "_layoutRecord">A <c>WHSLabelLayout</c> or <c>WHSDocumentRoutingLayout</c> record.</param>
/// <param name = "_sourceZplOverride">The edited source ZPL to translate and render.</param>
/// <param name = "_seedTableId">The seed table id, or 0 to resolve it from the layout.</param>
/// <param name = "_seedRecId">The seed record id, or 0 to use the most recent record.</param>
/// <param name = "_widthMm">The override width in millimeters, or 0 to use the label's own size.</param>
/// <param name = "_heightMm">The override height in millimeters, or 0 to use the label's own size.</param>
/// <param name = "_dpmm">The override density in dots per millimeter, or 0 to use the configured default.</param>
/// <returns>A populated <c>AAXWHSLabelPreviewContext</c>, or null when there is nothing to preview.</returns>
public static AAXWHSLabelPreviewContext renderFromSource(
    Common  _layoutRecord,
    str     _sourceZplOverride,
    TableId _seedTableId,
    RecId   _seedRecId,
    real    _widthMm = 0,
    real    _heightMm = 0,
    int     _dpmm = 0)
{
    // An empty source has nothing to preview
    if (!_sourceZplOverride)
    {
        return null;
    }

    return AAXWHSLabelPreviewController::buildContextFromSource(
        _layoutRecord, _sourceZplOverride, _seedTableId, _seedRecId, _widthMm, _heightMm, _dpmm);
}

/// <summary>
/// Shared pipeline for <c>buildContext</c> and <c>renderFromSource</c>. Resolves the source ZPL,
/// selects the plain or template translation path from the layout, binds the seed record and
/// sample data to the standard translator, renders the PNG images, and returns the populated
/// preview context.
/// </summary>
/// <param name = "_layoutRecord">A <c>WHSLabelLayout</c> or <c>WHSDocumentRoutingLayout</c> record.</param>
/// <param name = "_sourceZplOverride">The edited source ZPL, or an empty string to read the source from the layout.</param>
/// <param name = "_seedTableId">The seed table id, or 0 to resolve it from the layout.</param>
/// <param name = "_seedRecId">The seed record id, or 0 to use the most recent record.</param>
/// <param name = "_widthMm">The override width in millimeters, or 0 to use the label's own size.</param>
/// <param name = "_heightMm">The override height in millimeters, or 0 to use the label's own size.</param>
/// <param name = "_dpmm">The override density in dots per millimeter, or 0 to use the configured default.</param>
/// <returns>A populated <c>AAXWHSLabelPreviewContext</c>, or null when the layout cannot be previewed.</returns>
private static AAXWHSLabelPreviewContext buildContextFromSource(
    Common  _layoutRecord,
    str     _sourceZplOverride,
    TableId _seedTableId,
    RecId   _seedRecId,
    real    _widthMm = 0,
    real    _heightMm = 0,
    int     _dpmm = 0)
{
    AAXWHSLabelPreviewContext   context;
    WhsDocumentRoutingTranslator translator;
    Common                      seedRecord;
    DictTable                   seedDictTable;
    SysDictTable                seedSysDictTable;
    WHSLabelLayout              labelLayout;
    WHSDocumentRoutingLayout    documentRoutingLayout;
    TableId                     seedTableId = _seedTableId;
    boolean                     isTemplateLayout = false;
    str                         sourceZpl;
    str                         finalZpl;
    str                         badgeText;
    str                         layoutDescription = '';
    str                         seedTableLabel = '';
    LanguageId                  labelLocale = '';
    List                        pngList;

    if (!_layoutRecord || _layoutRecord.RecId == 0)
    {
        return null;
    }

    // Resolve the stored source and apply the layout resolution gates
    str layoutSource = AAXWHSLabelPreviewController::resolveLayoutZpl(_layoutRecord);
    if (!layoutSource)
    {
        return null;
    }

    // The edited override takes precedence over the stored source
    sourceZpl = _sourceZplOverride ? _sourceZplOverride : layoutSource;

    // Read the description and locale from the layout
    if (_layoutRecord.TableId == tableNum(WHSLabelLayout))
    {
        labelLayout = _layoutRecord as WHSLabelLayout;
        layoutDescription = labelLayout.Description;
        labelLocale = labelLayout.LabelLocale;
        isTemplateLayout = (labelLayout.EnableTemplateTranslator == NoYes::Yes);
    }
    else if (_layoutRecord.TableId == tableNum(WHSDocumentRoutingLayout))
    {
        documentRoutingLayout = _layoutRecord as WHSDocumentRoutingLayout;
        layoutDescription = documentRoutingLayout.Description;
    }

    // Resolve the seed table when the caller did not supply one
    if (!seedTableId)
    {
        seedTableId = AAXWHSLabelPreviewController::resolveSeedTable(_layoutRecord);
    }

    // Display label of the seed table for the dialog
    seedSysDictTable = SysDictTable::newTableId(seedTableId);
    if (seedSysDictTable)
    {
        seedTableLabel = seedSysDictTable.label();
    }

    // Template layouts run through the template translator pipeline
    if (isTemplateLayout)
    {
        context = AAXWHSLabelPreviewController::buildTemplateContext(
            labelLayout, sourceZpl, layoutDescription, labelLocale,
            seedTableId, seedTableLabel, _seedRecId, _widthMm, _heightMm, _dpmm);

        if (context)
        {
            // Carry the source and its savability for the dialog
            context.parmSourceZpl(sourceZpl);
            context.parmCanSave(true);

            // Stamp the size override so the dialog can repopulate its controls
            AAXWHSLabelPreviewController::stampSizeOverride(context, _widthMm, _heightMm, _dpmm);
        }

        return context;
    }

    // Resolve the seed record, defaulting to the most recent record
    seedDictTable = new DictTable(seedTableId);
    seedRecord = seedDictTable.makeRecord();

    if (_seedRecId != 0)
    {
        select firstonly seedRecord
            where seedRecord.RecId == _seedRecId;
    }
    else
    {
        select firstonly seedRecord
            order by RecId desc;
    }

    // Substitute tokens through the standard translator
    translator = WhsDocumentRoutingTranslator::construct();

    // Track the record names that receive a live binding so sample data never shadows them
    Set boundRecordNames = new Set(Types::String);

    if (seedRecord.RecId != 0)
    {
        // Unqualified tokens resolve from the record bound under the default name
        translator = translator.withRecord(seedRecord);
        boundRecordNames.add('');

        // Bind the seed record under its table name and any data source alias the ZPL references
        Set           seedNames    = AAXWHSLabelPreviewController::seedRecordNamesForTable(sourceZpl, tableId2Name(seedTableId));
        SetEnumerator seedNameEnum = seedNames.getEnumerator();
        str           seedName;

        while (seedNameEnum.moveNext())
        {
            seedName = seedNameEnum.current();
            translator = translator.withRecord(seedRecord, seedName);
            boundRecordNames.add(seedName);
        }

        badgeText = strFmt("@AAXWarehouseTools:LiveRecordBadge",
            AAXWHSLabelPreviewController::seedRecordIdentifier(seedRecord, seedTableId));
    }
    else
    {
        badgeText = "@AAXWarehouseTools:SampleDataBadge";
    }

    // Sample data serves the tokens that reference no record
    translator = translator.withParameterMap(AAXWHSLabelPreviewSampleData::sampleParameterMap());

    // Attach a sample map for every qualified record name that has no live binding
    translator = AAXWHSLabelPreviewController::attachQualifiedSampleMaps(translator, sourceZpl, boundRecordNames);

    // Apply the layout locale to the translator
    if (labelLocale)
    {
        translator = translator.withLanguage(labelLocale);
    }

    // Translate the source into the result shown in the dialog
    finalZpl = translator.translate(sourceZpl);

    // Render the translated ZPL
    pngList = AAXZplRenderService::renderToPngList(finalZpl, _dpmm, _widthMm, _heightMm);

    // Build the context with the layout identity and seed table for re-rendering
    context = new AAXWHSLabelPreviewContext();
    context.parmPngList(pngList);
    context.parmFinalZpl(finalZpl);
    context.parmSourceZpl(sourceZpl);   // RAW SOURCE — the editable/savable text
    context.parmCanSave(true);          // ZPL-type layouts (both tables) are savable in place
    context.parmBadgeText(badgeText);
    context.parmLayoutDescription(layoutDescription);
    context.parmLayoutTableId(_layoutRecord.TableId);
    context.parmLayoutRecId(_layoutRecord.RecId);
    context.parmSeedTableId(seedTableId);
    context.parmSeedRecId(seedRecord.RecId);
    context.parmSeedTableLabel(seedTableLabel);

    // Stamp the size override so the dialog can repopulate its controls
    AAXWHSLabelPreviewController::stampSizeOverride(context, _widthMm, _heightMm, _dpmm);

    return context;
}

/// <summary>
/// Records the size override on a preview context in the dialog units of inches and DPI so the
/// dialog can repopulate its label size controls. The override is on only when both a width
/// and a height were supplied.
/// </summary>
/// <param name = "_context">The context to update.</param>
/// <param name = "_widthMm">The override width in millimeters, or 0 for no override.</param>
/// <param name = "_heightMm">The override height in millimeters, or 0 for no override.</param>
/// <param name = "_dpmm">The override density in dots per millimeter, or 0 for the configured default.</param>
private static void stampSizeOverride(
    AAXWHSLabelPreviewContext _context,
    real                      _widthMm,
    real                      _heightMm,
    int                       _dpmm)
{
    boolean overrideOn = (_widthMm > 0 && _heightMm > 0);

    _context.parmOverrideSize(overrideOn);
    _context.parmOverrideWidthIn(_widthMm > 0 ? _widthMm / 25.4 : 0);
    _context.parmOverrideHeightIn(_heightMm > 0 ? _heightMm / 25.4 : 0);
    _context.parmOverrideDpi(_dpmm > 0 ? real2int(round(_dpmm * 25.4, 1.0)) : 0);
}

/// <summary>
/// Builds the preview context for a label layout that uses the template translator. Runs the
/// layout's data source query through <c>WhsDocumentRoutingTemplateTranslator</c>, renders each
/// produced label to PNG images, and returns the populated context.
/// </summary>
/// <param name = "_labelLayout">The template <c>WHSLabelLayout</c> record.</param>
/// <param name = "_templateSource">The template source ZPL of the layout.</param>
/// <param name = "_layoutDescription">The layout description shown in the dialog.</param>
/// <param name = "_labelLocale">The layout locale applied to the translator.</param>
/// <param name = "_seedTableId">The resolved seed table id.</param>
/// <param name = "_seedTableLabel">The display label of the seed table.</param>
/// <param name = "_seedRecId">The seed record id that scopes the row expansion, or 0 to expand the full query result.</param>
/// <param name = "_widthMm">The override width in millimeters, or 0 to use the label's own size.</param>
/// <param name = "_heightMm">The override height in millimeters, or 0 to use the label's own size.</param>
/// <param name = "_dpmm">The override density in dots per millimeter, or 0 to use the configured default.</param>
/// <returns>A populated <c>AAXWHSLabelPreviewContext</c>, or null when the layout has no data source.</returns>
private static AAXWHSLabelPreviewContext buildTemplateContext(
    WHSLabelLayout  _labelLayout,
    str             _templateSource,
    str             _layoutDescription,
    LanguageId      _labelLocale,
    TableId         _seedTableId,
    str             _seedTableLabel,
    RecId           _seedRecId,
    real            _widthMm = 0,
    real            _heightMm = 0,
    int             _dpmm = 0)
{
    AAXWHSLabelPreviewContext       context;
    WhsDocumentRoutingTranslator    translator;
    WHSLabelLayoutDataSource        layoutDataSource;
    Query                           query;
    QueryRun                        queryRun;
    List                            labelList;
    ListEnumerator                  labelEnum;
    List                            pngList = new List(Types::Container);
    str                             finalZpl = '';
    str                             badgeText;
    int                             labelCount;

    // A template layout requires a data source query
    if (!_labelLayout.LabelLayoutDataSource)
    {
        info("@AAXWarehouseTools:PreviewTemplateNoDataSource");
        return null;
    }

    select firstonly DataSourceQuery from layoutDataSource
        where layoutDataSource.LabelLayoutDataSourceId == _labelLayout.LabelLayoutDataSource;

    if (!layoutDataSource || layoutDataSource.DataSourceQuery == conNull())
    {
        info("@AAXWarehouseTools:PreviewTemplateNoDataSource");
        return null;
    }

    query = new Query(layoutDataSource.DataSourceQuery);

    // Scope the row expansion to the selected seed record
    if (_seedRecId > 0)
    {
        AAXWHSLabelPreviewController::addSeedRecIdRange(query, _seedRecId);
    }

    queryRun = new QueryRun(query);

    // A standard translator carrying the layout locale and the sample data for record-less tokens
    translator = WhsDocumentRoutingTranslator::construct();
    if (_labelLocale)
    {
        translator = translator.withLanguage(_labelLocale);
    }
    translator = translator.withParameterMap(AAXWHSLabelPreviewSampleData::sampleParameterMap());

    // Attach sample maps for record names the template iterator does not bind
    translator = AAXWHSLabelPreviewController::attachQualifiedSampleMaps(
        translator, _templateSource, AAXWHSLabelPreviewController::enabledDataSourceNames(query));

    // Expand the template into one entry per produced label
    labelList = WhsDocumentRoutingTemplateTranslator::newFromTemplateAndQueryRun(_templateSource, queryRun)
                    .withTranslator(translator)
                    .translateTemplate();

    // Render each produced label to its own PNG images
    if (labelList)
    {
        labelEnum = labelList.getEnumerator();
        while (labelEnum.moveNext())
        {
            str labelZpl = labelEnum.current();

            labelCount++;
            finalZpl += (finalZpl ? '\n\n' : '') + labelZpl;

            // A label may contain several ^XA..^XZ blocks, so append every image
            List labelPngs = AAXZplRenderService::renderToPngList(labelZpl, _dpmm, _widthMm, _heightMm);
            ListEnumerator pngEnum = labelPngs.getEnumerator();
            while (pngEnum.moveNext())
            {
                pngList.addEnd(pngEnum.current());
            }
        }
    }

    // Badge by the number of produced labels
    if (labelCount > 0)
    {
        badgeText = strFmt("@AAXWarehouseTools:TemplateDataBadge", labelCount);
    }
    else
    {
        badgeText = "@AAXWarehouseTools:SampleDataBadge";
    }

    context = new AAXWHSLabelPreviewContext();
    context.parmPngList(pngList);
    context.parmFinalZpl(finalZpl);
    context.parmBadgeText(badgeText);
    context.parmLayoutDescription(_layoutDescription);
    context.parmLayoutTableId(_labelLayout.TableId);
    context.parmLayoutRecId(_labelLayout.RecId);
    context.parmSeedTableId(_seedTableId);
    context.parmSeedRecId(_seedRecId);
    context.parmSeedTableLabel(_seedTableLabel);

    return context;
}

/// <summary>
/// Adds a RecId range for the seed record on the first enabled data source of a query so the
/// selected record drives the template row expansion. Failures are swallowed and leave the full
/// query result in place.
/// </summary>
/// <param name = "_query">The layout query.</param>
/// <param name = "_seedRecId">The seed record id.</param>
private static void addSeedRecIdRange(Query _query, RecId _seedRecId)
{
    QueryBuildDataSource    qbds;
    int                     dsCount;
    int                     i;

    try
    {
        dsCount = _query.dataSourceCount();
        for (i = 1; i <= dsCount; ++i)
        {
            qbds = _query.dataSourceNo(i);
            if (qbds && qbds.enabled())
            {
                qbds.addRange(fieldNum(Common, RecId)).value(queryValue(_seedRecId));
                return;
            }
        }
    }
    catch
    {
        // Leave the full query result on any failure
    }
}

/// <summary>
/// Collects the names of all enabled data sources of a query. These are the record names the
/// template iterator binds per row, which sample maps must not shadow.
/// </summary>
/// <param name = "_query">The layout query.</param>
/// <returns>A set of enabled data source names.</returns>
private static Set enabledDataSourceNames(Query _query)
{
    Set                     names = new Set(Types::String);
    QueryBuildDataSource    qbds;
    int                     dsCount;
    int                     i;

    if (!_query)
    {
        return names;
    }

    try
    {
        dsCount = _query.dataSourceCount();
        for (i = 1; i <= dsCount; ++i)
        {
            qbds = _query.dataSourceNo(i);
            if (qbds && qbds.enabled())
            {
                names.add(qbds.name());
            }
        }
    }
    catch
    {
        // A partial set is still safe because live rows win when no map exists for a name
    }

    return names;
}

/// <summary>
/// Returns a friendly identifier for a seed record for the live record badge.
/// </summary>
/// <param name = "_seedRecord">The bound seed record.</param>
/// <param name = "_seedTableId">The seed table id.</param>
/// <returns>The value of the table's first title field when available; otherwise the RecId.</returns>
private static str seedRecordIdentifier(Common _seedRecord, TableId _seedTableId)
{
    SysDictTable    dictTable = SysDictTable::newTableId(_seedTableId);
    FieldId         titleFieldId = dictTable ? dictTable.titleField1() : 0;
    str             titleValue;

    if (titleFieldId)
    {
        titleValue = any2Str(_seedRecord.(titleFieldId));
        if (titleValue)
        {
            return titleValue;
        }
    }

    return strFmt('RecId %1', _seedRecord.RecId);
}

/// <summary>
/// Scans layout ZPL for token placeholders and groups the referenced field names by record
/// name using the token grammar of <c>WhsDocumentRoutingTranslator</c>. Unqualified tokens are
/// grouped under the empty record name, and method tokens are excluded because a parameter map
/// cannot satisfy them.
/// </summary>
/// <param name = "_zpl">The source ZPL to scan.</param>
/// <returns>A map from record name to a set of field names.</returns>
public static Map scanRecordTokens(str _zpl)
{
    Map recordToFields = new Map(Types::String, Types::Class);

    if (!_zpl)
    {
        return recordToFields;
    }

    // The token grammar of the standard translator
    str fieldRegexString = @'\$(?:(?<record>[a-zA-Z0-9_]+?)\.)?(?<field>[a-zA-Z0-9_]+?)(?<methodIndicator>\(\))?(?:\[(?<lineIndex>[0-9]{1,3})\])?(?::(?<format>.*?))?\$';

    System.Text.RegularExpressions.Regex regex = new System.Text.RegularExpressions.Regex(fieldRegexString);
    System.Text.RegularExpressions.MatchCollection matches = regex.Matches(_zpl);
    System.Collections.IEnumerator enumerator = matches.GetEnumerator();

    while (enumerator.MoveNext())
    {
        System.Text.RegularExpressions.Match match = enumerator.Current;

        System.Text.RegularExpressions.Group recordGroup = match.Groups.get_Item('record');
        System.Text.RegularExpressions.Group fieldGroup  = match.Groups.get_Item('field');
        System.Text.RegularExpressions.Group methodGroup = match.Groups.get_Item('methodIndicator');

        if (!fieldGroup.Success)
        {
            // Nothing to substitute
            continue;
        }

        // Skip method tokens
        if (methodGroup.Success)
        {
            continue;
        }

        str recordName = recordGroup.Success ? recordGroup.Value : '';
        str fieldName  = fieldGroup.Value;

        Set fieldSet;
        if (recordToFields.exists(recordName))
        {
            fieldSet = recordToFields.lookup(recordName);
        }
        else
        {
            fieldSet = new Set(Types::String);
            recordToFields.insert(recordName, fieldSet);
        }

        fieldSet.add(fieldName);
    }

    return recordToFields;
}

/// <summary>
/// Returns the record names under which the seed record must be bound so its data flows into
/// record-qualified tokens: the table name plus any data source alias of the form table_n
/// that the ZPL references.
/// </summary>
/// <param name = "_zpl">The source ZPL to scan.</param>
/// <param name = "_seedTableName">The name of the seed table.</param>
/// <returns>A set of record names to bind the seed record under.</returns>
private static Set seedRecordNamesForTable(str _zpl, TableName _seedTableName)
{
    Set names = new Set(Types::String);

    if (!_seedTableName)
    {
        return names;
    }

    // Qualified tokens bind under the table name
    names.add(_seedTableName);

    str             aliasPrefixLower = strLwr(_seedTableName) + '_';
    int             prefixLen        = strLen(aliasPrefixLower);
    Map             recordToFields   = AAXWHSLabelPreviewController::scanRecordTokens(_zpl);
    MapEnumerator   tokenEnum        = recordToFields.getEnumerator();

    while (tokenEnum.moveNext())
    {
        str tokenName = tokenEnum.currentKey();

        // Data source aliases take the form table_n
        if (tokenName != '' && strLwr(subStr(tokenName, 1, prefixLen)) == aliasPrefixLower)
        {
            str suffix = subStr(tokenName, prefixLen + 1, strLen(tokenName) - prefixLen);
            if (suffix != '' && strKeep(suffix, '0123456789') == suffix)
            {
                names.add(tokenName);
            }
        }
    }

    return names;
}

/// <summary>
/// Attaches a named sample map to the translator for every record name in the ZPL tokens that has
/// no live binding, so record-qualified tokens resolve when their table has no live record.
/// Live-bound names and the empty record name are skipped so sample data never shadows live data.
/// </summary>
/// <param name = "_translator">The translator under construction.</param>
/// <param name = "_zpl">The source ZPL to scan.</param>
/// <param name = "_boundRecordNames">The record names that already have a live binding.</param>
/// <returns>The same translator instance.</returns>
public static WhsDocumentRoutingTranslator attachQualifiedSampleMaps(
    WhsDocumentRoutingTranslator _translator,
    str                          _zpl,
    Set                          _boundRecordNames)
{
    Map             recordToFields = AAXWHSLabelPreviewController::scanRecordTokens(_zpl);
    MapEnumerator   me             = recordToFields.getEnumerator();

    while (me.moveNext())
    {
        str recordName = me.currentKey();

        // Unqualified tokens are served by the sample parameter map and the seed record
        if (!recordName)
        {
            continue;
        }

        // Never shadow a live record bound under the same name
        if (_boundRecordNames && _boundRecordNames.in(recordName))
        {
            continue;
        }

        Set fieldSet  = me.currentValue();
        Map sampleMap = AAXWHSLabelPreviewSampleData::sampleMapForRecordTokens(recordName, fieldSet);

        if (sampleMap)
        {
            _translator = _translator.withParameterMap(sampleMap, recordName);
        }
    }

    return _translator;
}

/// <summary>
/// Writes an edited source ZPL back to its layout record for the dialog's save action. Document
/// routing layouts are updated directly; label layouts update the ZPL of the active version in
/// place. Writing requires edit access to the target table.
/// </summary>
/// <param name = "_layoutTableId">The table id of the layout record.</param>
/// <param name = "_layoutRecId">The RecId of the layout record.</param>
/// <param name = "_newSourceZpl">The source ZPL to save.</param>
/// <returns>A container of a success flag and the label of the message to show.</returns>
public static container saveSourceToLayout(
    TableId _layoutTableId,
    RecId   _layoutRecId,
    str     _newSourceZpl)
{
    WHSDocumentRoutingLayout    documentRoutingLayout;
    WHSLabelLayout              labelLayout;
    WHSLabelLayoutVersion       labelLayoutVersion;

    if (!_layoutTableId || !_layoutRecId)
    {
        return [false, "@AAXWarehouseTools:SaveFailed"];
    }

    switch (_layoutTableId)
    {
        case tableNum(WHSDocumentRoutingLayout):
            // Writing requires edit access to the target table
            if (!hasTableAccess(tableNum(WHSDocumentRoutingLayout), AccessType::Edit))
            {
                return [false, "@AAXWarehouseTools:SaveAccessDenied"];
            }

            // The ZPL is stored directly on the document routing layout
            ttsbegin;
            select forupdate firstonly documentRoutingLayout
                where documentRoutingLayout.RecId == _layoutRecId;

            if (documentRoutingLayout.RecId == 0)
            {
                ttsabort;
                return [false, "@AAXWarehouseTools:SaveLayoutGone"];
            }

            documentRoutingLayout.ZPL = _newSourceZpl;
            if (!documentRoutingLayout.validateWrite())
            {
                ttsabort;
                return [false, "@AAXWarehouseTools:SaveFailed"];
            }

            documentRoutingLayout.update();
            ttscommit;

            return [true, "@AAXWarehouseTools:SaveSucceeded"];

        case tableNum(WHSLabelLayout):
            // Writing requires edit access to the layout version table
            if (!hasTableAccess(tableNum(WHSLabelLayoutVersion), AccessType::Edit))
            {
                return [false, "@AAXWarehouseTools:SaveAccessDenied"];
            }

            select firstonly labelLayout
                where labelLayout.RecId == _layoutRecId;

            if (labelLayout.RecId == 0)
            {
                return [false, "@AAXWarehouseTools:SaveLayoutGone"];
            }

            // Only the ZPL definition type can be saved
            if (labelLayout.DefinitionType != WHSLabelLayoutDefinitionType::ZPL)
            {
                return [false, "@AAXWarehouseTools:SaveZplOnly"];
            }

            if (!labelLayout.ActiveVersion)
            {
                return [false, "@AAXWarehouseTools:SaveNoActiveVersion"];
            }

            // The source is stored on the active version
            ttsbegin;
            labelLayoutVersion = WHSLabelLayoutVersion::findByRecId(labelLayout.ActiveVersion, true);

            if (labelLayoutVersion.RecId == 0)
            {
                ttsabort;
                return [false, "@AAXWarehouseTools:SaveNoActiveVersion"];
            }

            labelLayoutVersion.ZPL = _newSourceZpl;
            if (!labelLayoutVersion.validateWrite())
            {
                ttsabort;
                return [false, "@AAXWarehouseTools:SaveFailed"];
            }

            labelLayoutVersion.update();
            ttscommit;

            return [true, "@AAXWarehouseTools:SaveSucceeded"];

        default:
            return [false, "@AAXWarehouseTools:SaveFailed"];
    }
}
